class MobileMenu extends HTMLElement {
  private backButtons: NodeListOf<HTMLButtonElement> | null = null;
  private submenuTriggers: NodeListOf<HTMLButtonElement> | null = null;

  constructor() {
    super();
  }

  connectedCallback() {
    this.cacheElements();
    this.bindEvents();
  }

  private cacheElements(): void {
    this.backButtons = this.querySelectorAll('[js-mobile-menu="close"]');
    this.submenuTriggers = this.querySelectorAll(
      '[js-mobile-menu="submenu-trigger"]',
    );
  }

  private bindEvents(): void {
    if (this.backButtons) {
      this.backButtons.forEach((button) => {
        button.addEventListener("click", this.handleBackButtonClick.bind(this));
      });
    }

    if (this.submenuTriggers) {
      this.submenuTriggers.forEach((button) => {
        button.addEventListener(
          "click",
          this.handleSubmenuTriggerClick.bind(this),
        );
      });
    }
  }

  private handleSubmenuTriggerClick(event: Event): void {
    const button = event.currentTarget as HTMLButtonElement;
    const submenuId = button.dataset.submenuId;

    if (!submenuId) {
      return;
    }

    const submenu = this.querySelector(
      `[js-mobile-menu="submenu"][data-submenu-id="${submenuId}"]`,
    );

    if (!submenu) {
      return;
    }

    submenu.classList.add("is-open");
    button.setAttribute("aria-expanded", "true");
    submenu.setAttribute("aria-expanded", "true");
  }

  private handleBackButtonClick(event: Event): void {
    const button = event.currentTarget as HTMLButtonElement;
    const detailsElement = button.closest('[js-mobile-menu="submenu"]');

    if (detailsElement) {
      (detailsElement as HTMLDivElement).classList.remove("is-open");
    }
  }
}

customElements.define("uwp-mobile-menu", MobileMenu);
